import{_ as r,c as e,o as t,ag as s}from"./chunks/framework._xRlcm3f.js";const o="/siyuan-plugin-publisher/images/shots/cors-workers.webp",i="/siyuan-plugin-publisher/images/shots/cors-triggers.webp",b=JSON.parse('{"title":"CORS 代理配置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cors-proxy.md","filePath":"guide/cors-proxy.md","lastUpdated":1790228279000}'),l={name:"guide/cors-proxy.md"};function n(d,a,h,p,c,g){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="cors-代理配置" tabindex="-1">CORS 代理配置 <a class="header-anchor" href="#cors-代理配置" aria-label="Permalink to &quot;CORS 代理配置&quot;">​</a></h1><p>部分平台在浏览器环境下受同源策略限制，需要经过一个中间服务器（CORS 代理）转发请求。</p><h2 id="为什么需要" tabindex="-1">为什么需要 <a class="header-anchor" href="#为什么需要" aria-label="Permalink to &quot;为什么需要&quot;">​</a></h2><p>思源的运行环境分两类：</p><table tabindex="0"><thead><tr><th>环境</th><th>是否有 CORS 限制</th></tr></thead><tbody><tr><td><strong>Node 环境</strong>（桌面端 Electron）：Windows、Linux、macOS</td><td>无限制</td></tr><tr><td><strong>纯浏览器环境</strong>：Docker 版、Android、iOS、浏览器访问</td><td><strong>有限制</strong></td></tr></tbody></table><p>浏览器有 CORS 限制是 Web 标准的要求，为了安全。插件有些平台的部分接口会触碰到它，于是需要一层代理：先把请求发给中间服务器（后端环境，本身不受 CORS 限制），由它转发并把结果返回。</p><div class="warning custom-block"><p class="custom-block-title">Docker 版与浏览器访问必须配置</p><p>受 CORS 策略限制，<strong>Docker 版本</strong>以及 Android、iOS、浏览器等环境<strong>必须设置 CORS 代理</strong>，否则大部分平台无法使用。桌面端通常不需要。</p></div><h2 id="代理的三种形态" tabindex="-1">代理的三种形态 <a class="header-anchor" href="#代理的三种形态" aria-label="Permalink to &quot;代理的三种形态&quot;">​</a></h2><p>插件按配置字段区分走哪条通路：</p><table tabindex="0"><thead><tr><th>形态</th><th>对应配置项</th><th>能力</th></tr></thead><tbody><tr><td><strong>cors-anywhere（自建通用代理）</strong></td><td>跨域代理地址</td><td>支持绕过受限请求头、请求体支持 FormData</td></tr><tr><td><strong>Cloudflare Workers</strong></td><td>跨域代理地址</td><td>同上，部署成本低</td></tr><tr><td><strong>内置中间件代理</strong>（旧版通路）</td><td>中间件地址</td><td>仅支持字符串请求体，<strong>不支持 FormData</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">图片上传必须用前两种</p><p>图片上传依赖 FormData，而旧版中间件只支持字符串请求体。因此带图发布必须使用 cors-anywhere 或 Cloudflare Workers 部署的通用代理。</p></div><h3 id="为什么没有现成的公共代理地址" tabindex="-1">为什么没有现成的公共代理地址 <a class="header-anchor" href="#为什么没有现成的公共代理地址" aria-label="Permalink to &quot;为什么没有现成的公共代理地址&quot;">​</a></h3><p>插件<strong>不内置</strong>通用代理地址，这不是遗漏，而是有意为之：</p><ul><li>通用代理需要转发<strong>全部请求内容</strong>，包括各平台凭据。集中到一个公共地址，等于把所有用户的凭据都经过同一个服务。</li><li>带宽与请求量成本高。一旦对外共享，很容易被滥用而耗尽额度甚至被封，结果反而是所有人都用不了。</li></ul><p>因此通用代理请按下文自行部署一份。<strong>配套的服务端部署源码也未公开分发</strong>，需要时发邮件索取即可（见各方式的说明）。</p><hr><h2 id="方式一-cors-anywhere-自建通用代理" tabindex="-1">方式一：cors-anywhere（自建通用代理） <a class="header-anchor" href="#方式一-cors-anywhere-自建通用代理" aria-label="Permalink to &quot;方式一：cors-anywhere（自建通用代理）&quot;">​</a></h2><p>这是最通用的方案，也是最早支持的一条通路：部署一个 <a href="https://github.com/Rob--W/cors-anywhere" target="_blank" rel="noreferrer">cors-anywhere</a> 服务，把地址填进「跨域代理地址」。</p><h3 id="源码获取" tabindex="-1">源码获取 <a class="header-anchor" href="#源码获取" aria-label="Permalink to &quot;源码获取&quot;">​</a></h3><p>插件配套的服务端部署源码<strong>未公开分发</strong>。需要时请发邮件到 <strong><a href="mailto:youweics@163.com" target="_blank" rel="noreferrer">youweics@163.com</a></strong> 索取，说明用途即可。</p><h3 id="部署要点" tabindex="-1">部署要点 <a class="header-anchor" href="#部署要点" aria-label="Permalink to &quot;部署要点&quot;">​</a></h3><ol><li>准备一台有 Node 环境的服务器。</li><li>部署 cors-anywhere 服务（或等价的自建通用代理），监听一个端口。</li><li>在浏览器打开该地址确认服务可访问。</li><li>把地址填进插件的「跨域代理地址」——<strong>带协议</strong>（<code>https://</code> 或 <code>http://</code>）、<strong>不含末尾斜杠</strong>。</li></ol><div class="warning custom-block"><p class="custom-block-title">不要使用来源不明的公共代理</p><p>公共代理能看到你发出的全部请求内容，包括平台凭据。务必使用自己部署或可信来源的代理。</p></div><hr><h2 id="方式二-cloudflare-workers" tabindex="-1">方式二：Cloudflare Workers <a class="header-anchor" href="#方式二-cloudflare-workers" aria-label="Permalink to &quot;方式二：Cloudflare Workers&quot;">​</a></h2><p>只需要一个自己的域名，适合没有常驻服务器的场景。</p><ol><li><p>注册并登录 <a href="https://www.cloudflare-cn.com/" target="_blank" rel="noreferrer">Cloudflare</a>。</p></li><li><p>解压部署包，安装依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>部署：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>过程中会要求登录 Cloudflare 账号。</p></li><li><p>在 <strong>Dashboard → Workers 和 Pages</strong> 里找到刚创建的 Worker：</p><p><img src="`+o+'" alt="在 Workers 和 Pages 里找到创建的 Worker" loading="lazy"></p></li><li><p>进入该项目，切到<strong>触发器</strong>页签，添加自定义域，指向你自己的域名（注意配置 CNAME 解析）：</p><p><img src="'+i+'" alt="在触发器页签添加自定义域" loading="lazy"></p></li><li><p>等待生效后，把该域名填进插件的「跨域代理地址」。</p></li></ol><p>部署源码同样请邮件到 <strong><a href="mailto:youweics@163.com" target="_blank" rel="noreferrer">youweics@163.com</a></strong> 索取。</p><hr><h2 id="方式三-内置中间件代理" tabindex="-1">方式三：内置中间件代理 <a class="header-anchor" href="#方式三-内置中间件代理" aria-label="Permalink to &quot;方式三：内置中间件代理&quot;">​</a></h2><p>插件内置的共享代理地址：<code>https://api.terwer.space/api/middleware</code>，对应配置里的「中间件地址」。</p><p>这条通路<strong>受较多限制</strong>：</p><ul><li>不支持绕过浏览器拒绝的请求头（如 <code>origin</code>、<code>referer</code>）</li><li>请求体<strong>只支持字符串</strong>，不支持 FormData 等二进制格式</li><li>只能代理 API 请求，不能代理普通网页</li></ul><p>因此它<strong>无法解决图片上传</strong>，也走不通 Telegraph 这类需要 FormData 的平台。其余大部分不含图片的场景仍可用。</p><div class="tip custom-block"><p class="custom-block-title">共享额度</p><p>这条通路由作者提供，请求量有限（历史上按「10 万次/天、1000 次/10 分钟」限制，且为所有人共享）。为保证可用性与稳定性，建议按下文自行部署方式一或方式二。</p></div><hr><h2 id="填写位置" tabindex="-1">填写位置 <a class="header-anchor" href="#填写位置" aria-label="Permalink to &quot;填写位置&quot;">​</a></h2><ul><li>平台级：设置 → 账号设置 → 对应平台的配置页 → <strong>跨域代理地址</strong></li><li>全局：设置 → 偏好设置</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="填了代理地址仍然失败" tabindex="-1">填了代理地址仍然失败 <a class="header-anchor" href="#填了代理地址仍然失败" aria-label="Permalink to &quot;填了代理地址仍然失败&quot;">​</a></h3><ol><li>先在浏览器直接打开代理地址，确认服务本身可访问。</li><li>确认地址<strong>带协议</strong>且<strong>不含末尾斜杠</strong>。</li><li>代理部署在本机时，注意 Docker 版思源里的 <code>localhost</code> 指向容器自身，需要改用宿主机地址。</li></ol><h3 id="图片上传失败-但文本发布正常" tabindex="-1">图片上传失败，但文本发布正常 <a class="header-anchor" href="#图片上传失败-但文本发布正常" aria-label="Permalink to &quot;图片上传失败，但文本发布正常&quot;">​</a></h3><p>说明当前走的是方式三（内置中间件），它不支持 FormData。请改用方式一或方式二，并把地址填进「跨域代理地址」。</p><h3 id="部署源码在哪里" tabindex="-1">部署源码在哪里 <a class="header-anchor" href="#部署源码在哪里" aria-label="Permalink to &quot;部署源码在哪里&quot;">​</a></h3><p>未公开分发。请发邮件到 <strong><a href="mailto:youweics@163.com" target="_blank" rel="noreferrer">youweics@163.com</a></strong> 索取，说明用途。</p><h3 id="桌面端也需要吗" tabindex="-1">桌面端也需要吗 <a class="header-anchor" href="#桌面端也需要吗" aria-label="Permalink to &quot;桌面端也需要吗&quot;">​</a></h3><p>通常不需要。桌面端是 Node 环境，没有 CORS 限制。个别平台因自身策略需要走代理时，插件会在配置页提示。</p>',47)])])}const k=r(l,[["render",n]]);export{b as __pageData,k as default};
